```c
#include <stdio.h>
int main() {
    int N, M, encuestador, formulario;
    float puntaje, sumaEncuestador, sumaPromedios, promedioEnc, promedioGeneral;
    scanf("%d %d", &N, &M);
    sumaPromedios = 0;
    encuestador = 1;
    while (encuestador <= N) {
        sumaEncuestador = 0;
        formulario = 1;
        while (formulario <= M) {
            scanf("%f", &puntaje);
            sumaEncuestador += puntaje;
            formulario++;
        }
        promedioEnc = sumaEncuestador / M;
        printf("Encuestador %d: promedio %.2f\n", encuestador, promedioEnc);
        sumaPromedios += promedioEnc;
        encuestador++;
    }
    promedioGeneral = sumaPromedios / N;
    printf("Promedio general: %.2f\n", promedioGeneral);
    return 0;
}
```

Nítido, eso está correcto y bien estructurado. Revisemos juntos la lógica de cada decisión antes de dar el código final:

```c
#include <stdio.h>

int main() {
    int N, M;
    int encuestador, formulario;
    float puntaje;
    float sumaEncuestador; /* se resetea por encuestador: DENTRO del while externo */
    float sumaPromedios;   /* acumula promedios: se inicializa UNA vez ANTES del while externo */
    float promedioEnc, promedioGeneral;

    printf("Numero de encuestadores: ");
    scanf("%d", &N);
    printf("Encuestas por encuestador: ");
    scanf("%d", &M);

    sumaPromedios = 0.0; /* una sola vez, fuera de ambos bucles */

    encuestador = 1;
    while (encuestador <= N) {
        sumaEncuestador = 0.0; /* reset al inicio de cada encuestador */
        formulario = 1;        /* reset al inicio de cada encuestador */

        while (formulario <= M) {
            printf("  Puntaje formulario %d: ", formulario);
            scanf("%f", &puntaje);
            sumaEncuestador += puntaje; /* acumula solo para este encuestador */
            formulario++;
        }

        /* promedio del encuestador: se calcula después del while interno */
        promedioEnc = sumaEncuestador / M;
        printf("Encuestador %d: promedio = %.2f\n", encuestador, promedioEnc);

        sumaPromedios += promedioEnc; /* agrega al acumulador de nivel externo */
        encuestador++;
    }

    /* promedio general: se calcula después del while externo */
    promedioGeneral = sumaPromedios / N;
    printf("Promedio general del operativo: %.2f\n", promedioGeneral);

    return 0;
}
```

Cada variable responde a la pregunta "¿a qué nivel pertenece este dato?" y se inicializa exactamente ahí.
